use semio_framework_test_fixtures::fixture_text;
use super::*;
use crate::observe_retirement_allocations as observe;

fn denied(grant:RetainedCloneGrant,copy_demand:usize)->Vec<RetainedCloneGrant>{
    [Some(RetainedCloneGrant {maximum_items:0,..grant}),copy_demand.checked_sub(1).map(|maximum_copy_bytes|RetainedCloneGrant {maximum_copy_bytes,..grant}),grant.maximum_capacity_bytes.checked_sub(1).map(|maximum_capacity_bytes|RetainedCloneGrant {maximum_capacity_bytes,..grant}),grant.maximum_release_bytes.checked_sub(1).map(|maximum_release_bytes|RetainedCloneGrant {maximum_release_bytes,..grant}),grant.maximum_depth.checked_sub(1).map(|maximum_depth|RetainedCloneGrant {maximum_depth,..grant}),(grant.maximum_release_bytes>8).then_some(RetainedCloneGrant {maximum_release_bytes:8,..grant})].into_iter().flatten().collect()
}

fn check_denied(turn:RetainedWorkOutcome,heap:(usize,usize),grant:RetainedCloneGrant,admitted:RetainedCloneGrant){
    assert_eq!(turn.work,0);let result=turn.result;assert_eq!(heap,(0,0));match result{Ok(step)=>assert_eq!(step.progress(),Default::default()),Err(error)=>{assert!(grant.maximum_depth<admitted.maximum_depth);assert_eq!(error.kind,ValueRefusalKind::DepthLimit);assert_eq!(error.retained_progress(),Default::default());}}
}

#[test]
fn original_scalar_clone_requires_original_authority(){
    let law:serde_json::Value=serde_json::from_str(fixture_text!("../../../🧮️scalar/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
    for encoded in law["values"].as_array().unwrap(){let value:u64=encoded.as_str().unwrap().parse().unwrap();for copy in law["copyGrants"].as_array().unwrap(){let copy=copy.as_u64().unwrap()as usize;for cancelled in [None,Some(0),Some(1)]{let mut cpu=law["closeWork"]["maximumCpu"].as_u64().unwrap();
        let mut admission=RetainedCloneSource::admission_owned(value,());let mut published=None;let(mut born,mut freed)=(0,0);for _ in 0..10000{if admission.terminal_is_empty(){break}let d=admission.next_demand().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(turn,heap)=observe(||if admission.phase()=="ready"{admission.take_output(&mut published,grant)}else{admission.advance(grant)});cpu=cpu.checked_sub(turn.work).expect("same finite scalar CPU bank");let p=match &turn.result{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};assert!(p.fits(grant));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));born+=heap.0;freed+=heap.1;turn.result.unwrap();}assert!(admission.terminal_is_empty());let mut source=published.expect("scalar staged source publication");let original=source.borrow().get()as *const u64;
        let(mut cursor,heap)=observe(u64::retained_clone_cursor);assert_eq!(heap,(0,0));let normal=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:law["payloadBytes"].as_u64().unwrap()as usize,maximum_depth:law["depth"].as_u64().unwrap()as usize,..Default::default()};
        if cancelled!=Some(0){for denied in [RetainedCloneGrant {maximum_items:0,..normal},RetainedCloneGrant {maximum_copy_bytes:0,..normal},RetainedCloneGrant {maximum_copy_bytes:normal.maximum_copy_bytes-1,..normal},RetainedCloneGrant {maximum_depth:0,..normal}]{let bound=cursor.source.is_some();let(turn,heap)=observe(||cursor.advance(source.borrow(),normal.maximum_copy_bytes,denied));assert_eq!(turn.work,law["advanceWork"]["deniedCpu"].as_u64().unwrap());let result=turn.result;assert_eq!(heap,(0,0));match result{Ok(step)=>assert_eq!(step.progress(),Default::default()),Err(error)=>{assert_eq!(denied.maximum_depth,0);assert_eq!(error.kind,ValueRefusalKind::DepthLimit);assert_eq!(error.retained_progress(),Default::default());}}assert_eq!(cursor.source.is_some(),bound,"Original scalar denial cannot bind an unadmitted source lease");assert_eq!(source.borrow().get()as *const u64,original);assert!(cursor.value.is_none());}
            if cursor.source.is_none(){let funded=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:cursor.advance_demands(source.borrow(),normal.maximum_copy_bytes).unwrap().copy_bytes,maximum_depth:normal.maximum_depth,..Default::default()};let(result,heap)=observe(||cursor.advance(source.borrow(),normal.maximum_copy_bytes,funded));assert_eq!(result.work,law["advanceWork"]["bindingCpu"].as_u64().unwrap());cpu-=result.work;let bind=result.result.unwrap();assert_eq!(funded.maximum_copy_bytes,law["bindingAdmissionBytes"].as_u64().unwrap()as usize);assert_eq!(source.borrow().binding_copy_bytes(),law["bindingCopyBytes"].as_u64().unwrap()as usize);assert!(matches!(bind,RetainedCloneStep::Progress(_)));assert_eq!(heap,(0,0));assert_eq!(bind.progress(),RetainedCloneProgress {copied_items:1,copied_bytes:source.borrow().binding_copy_bytes(),..Default::default()});}
            let(result,heap)=observe(||cursor.advance(source.borrow(),normal.maximum_copy_bytes,normal));assert_eq!(result.work,law["advanceWork"]["payloadCpu"].as_u64().unwrap());cpu-=result.work;let step=result.result.unwrap();assert!(matches!(step,RetainedCloneStep::Complete(_)));assert_eq!(heap,(0,0));assert_eq!(step.progress(),RetainedCloneProgress {copied_items:1,copied_bytes:8,..Default::default()});if cancelled.is_none(){let(turn,heap)=observe(||cursor.take(normal));cpu=cpu.checked_sub(turn.work).expect("same finite scalar CPU bank");assert_eq!(turn.work,1);let output=turn.result.unwrap();assert_eq!(heap,(0,0));assert_eq!(output,Some((value,RetainedCloneProgress{copied_items:1,..Default::default()})));}
        }
        assert_eq!(observe(||cursor.begin_close()).1,(0,0));let mut turns=0;while !cursor.terminal_is_empty(){let d=cursor.close_demands(copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert_eq!(cursor.close_demands(grant.maximum_copy_bytes).unwrap(),d);for denied in denied(grant,d.copy_bytes){let(result,heap)=observe(||cursor.close_step(denied));check_denied(result,heap,denied,grant);}let(result,heap)=observe(||cursor.close_step(grant));cpu=cpu.checked_sub(result.work).expect("same finite close CPU bank");let step=result.result.unwrap();assert!(step.progress().fits(grant));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<10000);}
        let cached=cursor.close_step(Default::default());assert_eq!(cached.work,law["closeWork"]["cachedCpu"].as_u64().unwrap());assert_eq!(cached.result.unwrap().progress(),Default::default());assert_eq!(observe(||drop(cursor)).1,(0,0));while !source.terminal_is_empty(){let d=source.next_close_demand(copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert_eq!(source.next_close_demand(grant.maximum_copy_bytes).unwrap(),d);for denied in denied(grant,d.copy_bytes){let(result,heap)=observe(||source.close_step(denied));check_denied(result,heap,denied,grant);}let(result,heap)=observe(||source.close_step(grant));cpu=cpu.checked_sub(result.work).expect("same finite close CPU bank");let step=result.result.unwrap();assert!(step.progress().fits(grant));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<10000);}assert_eq!(observe(||drop(source)).1,(0,0));assert_eq!(born,freed);
    }}}
}

#[test]
fn scalar_lifecycle_state_matrix_preserves_private_cursor_phase(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../../🧮️scalar/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for row in law["lifecycle"].as_array().unwrap(){let mut cursor=ScalarCursor::<u64>::default();cursor.value=row["output"].as_bool().unwrap().then_some(42);cursor.closing=row["closing"].as_bool().unwrap();cursor.spent=row["spent"].as_bool().unwrap();assert_eq!(cursor.output_ready(),row["ready"].as_bool().unwrap());if !cursor.output_ready(){let turn=cursor.take(Default::default());assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());}cursor.value=None;}
}
